class OASISv3AIFactory(OASISv3AIFactory):  # Extending the previous class

    def analyze_sentiment(self, text: str) -> Dict[str, Any]:
        """
        Analyze sentiment of input text using RoBERTa model
        """
        if not text.strip():
            return {"success": False, "error": "Empty text provided"}

        payload = {"inputs": text}
        result = self.make_hf_request("sentiment", payload)

        if result["success"] and result["data"]:
            # Process sentiment results
            sentiment_data = result["data"]
            if isinstance(sentiment_data, list) and len(sentiment_data) > 0:
                scores = sentiment_data[0] if isinstance(sentiment_data[0], list) else sentiment_data

                # Format results for easy consumption
                formatted_results = []
                for item in scores:
                    formatted_results.append({
                        "label": item.get("label", "Unknown"),
                        "confidence": round(item.get("score", 0), 4)
                    })

                result["formatted_results"] = formatted_results
                result["primary_sentiment"] = max(formatted_results, key=lambda x: x["confidence"])

                # Calculate revenue (example: $0.01 per sentiment analysis)
                self.session_stats["revenue_generated"] += 0.01

        return result

    def detect_emotion(self, text: str) -> Dict[str, Any]:
        """
        Detect emotions in input text
        """
        if not text.strip():
            return {"success": False, "error": "Empty text provided"}

        payload = {"inputs": text}
        result = self.make_hf_request("emotion", payload)

        if result["success"] and result["data"]:
            emotion_data = result["data"]
            if isinstance(emotion_data, list) and len(emotion_data) > 0:
                scores = emotion_data[0] if isinstance(emotion_data[0], list) else emotion_data

                formatted_results = []
                for item in scores:
                    formatted_results.append({
                        "emotion": item.get("label", "Unknown"),
                        "confidence": round(item.get("score", 0), 4)
                    })

                result["formatted_results"] = formatted_results
                result["dominant_emotion"] = max(formatted_results, key=lambda x: x["confidence"])
                self.session_stats["revenue_generated"] += 0.015  # $0.015 per emotion analysis

        return result

    def generate_text(self, prompt: str, max_length: int = 100) -> Dict[str, Any]:
        """
        Generate text based on input prompt
        """
        if not prompt.strip():
            return {"success": False, "error": "Empty prompt provided"}

        payload = {
            "inputs": prompt,
            "parameters": {
                "max_length": max_length,
                "temperature": 0.7,
                "do_sample": True
            }
        }
        result = self.make_hf_request("text_generation", payload)

        if result["success"] and result["data"]:
            generation_data = result["data"]
            if isinstance(generation_data, list) and len(generation_data) > 0:
                generated_text = generation_data[0].get("generated_text", "")
                result["generated_text"] = generated_text
                result["word_count"] = len(generated_text.split())
                self.session_stats["revenue_generated"] += 0.05  # $0.05 per text generation

        return result

    def summarize_text(self, text: str, max_length: int = 150) -> Dict[str, Any]:
        """
        Summarize input text using BART model
        """
        if not text.strip():
            return {"success": False, "error": "Empty text provided"}

        payload = {
            "inputs": text,
            "parameters": {
                "max_length": max_length,
                "min_length": 30,
                "do_sample": False
            }
        }
        result = self.make_hf_request("summarization", payload)

        if result["success"] and result["data"]:
            summary_data = result["data"]
            if isinstance(summary_data, list) and len(summary_data) > 0:
                summary_text = summary_data[0].get("summary_text", "")
                result["summary"] = summary_text
                result["compression_ratio"] = round(len(summary_text) / len(text), 3)
                self.session_stats["revenue_generated"] += 0.03  # $0.03 per summarization

        return result

    def translate_text(self, text: str, source_lang: str = "en", target_lang: str = "es") -> Dict[str, Any]:
        """
        Translate text from source to target language
        """
        if not text.strip():
            return {"success": False, "error": "Empty text provided"}

        payload = {"inputs": text}
        result = self.make_hf_request("translation", payload)

        if result["success"] and result["data"]:
            translation_data = result["data"]
            if isinstance(translation_data, list) and len(translation_data) > 0:
                translated_text = translation_data[0].get("translation_text", "")
                result["translated_text"] = translated_text
                result["source_language"] = source_lang
                result["target_language"] = target_lang
                self.session_stats["revenue_generated"] += 0.02  # $0.02 per translation

        return result

